type DeepPartial<T> = T extends any[] ? T : {
  [P in keyof T]?: DeepPartial<T[P]>;
};
type ProcessorAttributesWithInvocationResults = {[K in keyof ProcessorAttributes]: K extends keyof InvocationProcessorOutputAttribute ? ProcessorAttributes[K] & { result: InvocationProcessorOutputAttribute[K] } : ProcessorAttributes[K];};
type TestInvocationResult = Omit<Invocation, "processors"> & {processors: ProcessorAttributesWithInvocationResults; outlet: string;};

export const TestDriver: ITestDriver;

export interface InvocationProcessorInputAttribute {
  runProjectExport: RunProjectExportInput;
  exportProjectCustomers: ExportProjectCustomersInput;
  exportProjectOccurrences: ExportProjectOccurrencesInput;
  exportProjectSocialMediaPost: ExportProjectSocialMediaPostInput;
}

export interface InvocationProcessorOutputAttribute {
  runProjectExport: RunProjectExportOutput;
  exportProjectCustomers: ExportProjectCustomersOutput;
  exportProjectOccurrences: ExportProjectOccurrencesOutput;
  exportProjectSocialMediaPost: ExportProjectSocialMediaPostOutput;
}

export interface InterfaceTestProcessorAttribute<T extends keyof ProcessorAttributes> {
  attribute<Q extends keyof ProcessorAttributes[T]>(attributeId: Q, value: ProcessorAttributes[T][Q]): InterfaceTestProcessorAttribute<T>;
  attributes(attributes: DeepPartial<ProcessorAttributes[T]>): InterfaceTestProcessorAttribute<T>;
}

export interface InterfaceTest {
  withLogLevel(logLevel: 'off' | 'error' | 'warn' | 'info' | 'debug' | 'trace'): InterfaceTest;
  startWith<K extends keyof ProcessorAttributes>(...args: K extends keyof InvocationProcessorInputAttribute ? [processorIdentifier: K, input?: InvocationProcessorInputAttribute[K]] : [processorIdentifier: K]): InterfaceTest;
  stopBefore(...processorIdentifiers: (keyof ProcessorAttributes)[]): InterfaceTest;
  stopAfter(...processorIdentifiers: (keyof ProcessorAttributes)[]): InterfaceTest;
  processorAttributes<T extends keyof ProcessorAttributes>(processorIdentifier: T, processorAttributeFunction: (processorAttributes: InterfaceTestProcessorAttribute<T>) => void): InterfaceTest;
  invocationAttribute<T extends keyof InvocationAttributes>(attributeId: T, value: InvocationAttributes[T]): InterfaceTest;
  invocationAttributes(attributes: DeepPartial<InvocationAttributes>): InterfaceTest;
  mock<T extends keyof ProcessorAttributes>(processorIdentifier: T, mockFunction?: (mock: ProcessorMock<T>, currentInvocation: Invocation) => void): InterfaceTest;
  test(): TestInvocationResult;
}

export interface ProcessorMock<T extends keyof ProcessorAttributes> {
  processorAttribute<Q extends keyof ProcessorAttributes[T]>(attributeId: Q, value: ProcessorAttributes[T][Q]): ProcessorMock<T>;
  processorAttributes(attributes: DeepPartial<ProcessorAttributes[T]>): ProcessorMock<T>;
  invocationAttribute<Q extends keyof InvocationAttributes>(attributeId: Q, value: InvocationAttributes[Q]): ProcessorMock<T>;
  invocationAttributes(attributes: DeepPartial<InvocationAttributes>): ProcessorMock<T>;
  outlet(outletName: string): ProcessorMock<T>;
}

interface ITestDriver {
  createTest(): InterfaceTest;
}

